public sealed class MatchTarget {public int Seat,UnitId;public MatchTarget(){}public MatchTarget(int seat,int unitId=0){Seat=seat;UnitId=unitId;}public bool Hero{get{return UnitId==0;}}}
public sealed class HandCard {public int Id;public string CardId;public bool Generated;}
public sealed class BattleUnit {
 public int Id,Owner,BaseAttack,BaseHealth,BuffAttack,BuffHealth,DamageTaken,AuraHealth,TempAttack,AttacksUsed,SummonTurn,FrozenTurn,DeathAnchor,ForestDeathrattles,WisdomBlessings0,WisdomBlessings1;
 public int OriginalOwner,DestroyAtEnd=-1,DestroyAtStart0=-1,DestroyAtStart1=-1,ReturnSeat=-1,ReturnTurn=-1;
 public string CardId,Race;public bool Taunt,Shield,Windfury,Charge,Poison,Stealth,Frozen,Silenced;
