public sealed class MatchPlayer {
 public string ClassId;public int Health=30,Armor,MaxMana,Mana,Overload,LockedMana,Fatigue,SecretCount,MinionsPlayedThisTurn,HeroAttacks,TempAttack,FrozenTurn;
 public bool Frozen,PowerUsed;public string WeaponId;public int WeaponAttack,WeaponDurability;public bool WeaponWindfury;
